<!--
 * 系统配置管理页面 — 参数配置的分页列表、搜索、新增、编辑、删除
 *
 * @path apps\system-web\src\views\config\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 系统配置（列表页）
 * <p>消费后端契约 ConfigController（src/api/config.ts，auto-generated by bash/gen-contract.py）的系统配置列表页：
 * 分页查询 page、编辑/删除（remove）。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page, useYDSZModal } from '@ydsz/common-ui';

import { createLogger } from '@ydsz-core/shared/utils';
import { ElButton, ElMessage, ElMessageBox, ElTag } from 'element-plus';
import { computed, h, ref } from 'vue';
import { useI18n } from 'vue-i18n';

import { useAccess } from '@ydsz/access';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { page, remove } from '#/api/config';
import type { ConfigPageQuery, ConfigVO, PageQuery } from '#/api/models';

import ConfigForm from './config-form.vue';
import ConfigHistoryDialog from './config-history-dialog.vue';

defineOptions({ name: 'ConfigManagement' });

/** 按钮级权限判断 + 数据范围（行级权限） */
const { hasAccessByCodesAll, getDataScope } = useAccess();

const logger = createLogger('system-config');

const { t } = useI18n();

/**
 * 数据范围（行级数据权限）。
 * - 资源类型标识: 'system:config'（系统配置）
 * - 返回值语义:
 *   - undefined: 未受限，可访问全部数据
 *   - 非空数组/对象: 受限，仅可访问指定范围
 * 由后端登录接口注入，当前仅做前端展示（后端 dataScope 过滤 TODO）。
 */
const dataScope = ref<unknown>(getDataScope('system:config'));

/** 数据范围展示标签（无约束时不渲染） */
const dataScopeLabel = computed(() => {
  const scope = dataScope.value;
  if (scope === undefined || scope === null) return '';
  if (Array.isArray(scope)) return `数据范围: 限定 ${scope.length} 项`;
  if (typeof scope === 'object') return '数据范围: 自定义约束';
  return `数据范围: ${String(scope)}`;
});

/** 行类型：真实契约 ConfigVO（字段以 models.ts 为准） */
type ConfigRow = ConfigVO;

/** 分页查询参数：契约 ConfigPageQuery + 通用分页字段（models.ts PageQuery） */
type ConfigPageQueryParams = ConfigPageQuery & PageQuery;

/** 状态是否启用（后端 status 为字符串，兼容 '1' / 'ENABLED' 两种取值） */
function isEnabled(status?: string): boolean {
  return status === '1' || status === 'ENABLED';
}

const gridOptions: VxeTableGridOptions<ConfigRow> = {
  columns: [
    { type: 'seq', width: 50, title: t('common.seq') },
    { field: 'configKey', title: t('configKey'), width: 180 },
    { field: 'configValue', title: t('configValue'), width: 200 },
    { field: 'configGroup', title: t('configGroup'), width: 130 },
    { field: 'valueType', title: t('variable.valueType'), width: 100 },
    { field: 'isPublic', title: t('isPublic'), width: 70 },
    {
      field: 'status',
      title: t('status'),
      width: 80,
      slots: {
        default: ({ row }) => {
          return h(
            ElTag,
            { type: isEnabled(row.status) ? 'success' : 'info' },
            () => (isEnabled(row.status) ? t('enabled') : t('disabled')),
          );
        },
      },
    },
    { field: 'description', title: t('description'), width: 180 },
    {
      field: 'action',
      title: t('action'),
      width: 220,
      fixed: 'right',
      slots: {
        default: ({ row }) => {
          const buttons = [];
          // 编辑按钮 — 需要 sys:config:edit 权限
          if (hasAccessByCodesAll(['sys:config:edit'])) {
            buttons.push(h(ElButton, { size: 'small', link: true, type: 'primary', onClick: () => handleEdit(row) }, () => t('edit')));
          }
          // 版本历史按钮 — 需要 sys:config:edit 权限
          if (hasAccessByCodesAll(['sys:config:edit'])) {
            buttons.push(h(ElButton, { size: 'small', link: true, type: 'warning', onClick: () => handleVersionHistory(row) }, () => t('configVersion.history')));
          }
          // 删除按钮 — 需要 sys:config:delete 权限
          if (hasAccessByCodesAll(['sys:config:delete'])) {
            buttons.push(h(ElButton, { size: 'small', link: true, type: 'danger', onClick: () => handleDelete(row) }, () => t('delete')));
          }
          return h('div', { class: 'flex gap-1' }, buttons);
        },
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async ({ page: pageInfo }, formValues) => {
        const query: ConfigPageQueryParams = {
          pageNum: pageInfo.currentPage,
          pageSize: pageInfo.pageSize,
          ...formValues,
        };
        const res = await page({ query });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      { field: 'configKey', title: t('configKey'), itemRender: { name: 'Input', props: { placeholder: t('configKey') } } },
      { field: 'configGroup', title: t('configGroup'), itemRender: { name: 'Input', props: { placeholder: t('configGroup') } } },
    ],
  },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });

const [ConfigFormModal, configFormApi] = useYDSZModal({ connectedComponent: ConfigForm });

/** 版本历史抽屉引用 */
const historyDialogRef = ref<InstanceType<typeof ConfigHistoryDialog>>();

function handleAdd() {
  configFormApi.open();
}

function handleEdit(row: ConfigRow) {
  configFormApi.setData({ record: row });
  configFormApi.open();
}

function handleVersionHistory(row: ConfigRow) {
  historyDialogRef.value?.open(row.configKey ?? '');
}

async function handleDelete(row: ConfigRow) {
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await ElMessageBox.confirm(t('confirmDeleteName', [row.configKey ?? '']), t('common.deleteConfirm'), { type: 'warning' });
  } catch (error) {
    logger.warn('用户取消删除系统配置', error);
    return; // 用户主动取消删除操作
  }
  // 步骤2：执行删除 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    if (row.id) await remove({ id: row.id });
    ElMessage.success(t('operationSuccess'));
    gridApi.query();
  } catch (error) {
    logger.warn('删除系统配置失败，详见拦截器提示', error);
    // 用户提示由 errorMessageResponseInterceptor 统一处理
  }
}
</script>

<template>
  <Page auto-content-height>
    <Grid :table-title="t('config')">
      <template #toolbar-tools>
        <ElTag v-if="dataScopeLabel" type="warning" size="small" style="margin-right: 8px">
          {{ dataScopeLabel }}
        </ElTag>
        <ElButton v-permission="'sys:config:add'" type="primary" @click="handleAdd">{{ t('create') }}</ElButton>
      </template>
    </Grid>
    <ConfigFormModal @success="gridApi.query()" />
    <ConfigHistoryDialog ref="historyDialogRef" @success="gridApi.query()" />
  </Page>
</template>